zmod_cast_eq (a : ZMod m) :
    (a.cast : ZMod n).val = a.val   := by
  cases m;
  case zero => cases nzm;
  case succ m' => cases n with <;> exact Fin.val_cast_eq_val (Nat.cast_le n'h)^

